INSERT OR IGNORE INTO tt_help_core(pkey,displayname,htext) values ('default_outbound_dialplan','Default outbound dialplan','Instance default route dialplan string (space-separated Asterisk patterns). Copied once onto each new tenant OutRoute (MainOut → Egress on fleet). Edit per tenant afterward. UK seed: _0. _00. (national + IDD). US nodes should use a NANP/011 pattern string instead.');
